evaluation.reference:
Algorithm Stopwatch
  Define seconds As Integer <- 3725;
  Define hours As Integer <- seconds Div 3600;
  Define minutes As Integer <- seconds Mod 3600 Div 60;
  Write hours, " h ", minutes, " min ", seconds Mod 60, " s";
EndAlgorithm
